function step(ctx) {
  if (ctx.phase === "start") {
    return {
      action: "http",
      state: null,
      request: {
        method: "POST",
        url: "images/generations",
        headers: { Authorization: "Bearer " + ctx.settings.apiKey },
        json: {
          model: ctx.settings.model,
          prompt: ctx.prompt,
          size: ctx.settings.size,
          response_format: "b64_json"
        }
      }
    };
  }
  if (ctx.response.status < 200 || ctx.response.status >= 300) {
    var message = "生图服务返回 HTTP " + ctx.response.status;
    try {
      var errorPayload = JSON.parse(ctx.response.text);
      if (errorPayload.error && errorPayload.error.message) message += ":" + errorPayload.error.message;
    } catch (_) {}
    return { action: "error", message: message };
  }
  var payload = JSON.parse(ctx.response.text);
  var images = [];
  for (var i = 0; i < payload.data.length; i++) {
    if (payload.data[i].b64_json) images.push({ base64: payload.data[i].b64_json });
  }
  if (images.length === 0) return { action: "error", message: "响应中没有 b64_json 图片" };
  return { action: "done", images: images };
}
